-- Bloco 1: reescreve somente dicas e passos das primeiras 33 questões MC.
-- Enunciados, alternativas, gabaritos, tags e explicações permanecem intactos.
begin;

create temporary table c1_block_01_steps (
  question_id uuid primary key, hints text[] not null, titles text[] not null, steps text[] not null
) on commit drop;


select format('00000082-0000-4000-8000-%s',lpad((row_number() over(order by question_id)*10+ord)::text,12,'0'))::uuid,
question_id,hint,ord
from c1_block_01_steps cross join lateral unnest(hints) with ordinality as h(hint,ord)
on conflict (question_id,sort_order) do update set content_markdown=excluded.content_markdown;

select format('00000092-0000-4000-8000-%s',lpad((row_number() over(order by question_id)*10+ord)::text,12,'0'))::uuid,
question_id,title,step,ord
from c1_block_01_steps
cross join lateral unnest(titles) with ordinality as t(title,ord)
cross join lateral unnest(steps) with ordinality as s(step,step_ord)
where ord=step_ord
on conflict (question_id,sort_order) do update set title=excluded.title,content_markdown=excluded.content_markdown;

commit;
